using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SingingUrnOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/SingingUrnOmenData")]
public class SingingUrnOmenData : OnStartOfBattleOmenData
{
	[Header("Singing Urn Omen Data")]
	[SerializeField]
	private ChantingEffect chantingEffect;

	[SerializeField]
	private OmenLogicActionFace purificationOmenLogicActionFace;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.SingingUrnOmenAction = delegate(int chantingAmount)
		{
			omenInstance.EnqueueOmenFeedbackAndPlay();
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, 2, delegate
			{
				purificationOmenLogicActionFace.OmenLogic.ActivateOmen(null, chantingAmount * purificationOmenLogicActionFace.ActionFace.ActionValue, null, null);
			});
		};
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.SingingUrnOmenAction = null;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		string arg = Smart.Format(base.localizationManager.GetLocalizedForEach(), purificationOmenLogicActionFace.ActionFace.BattleAction.GetActionDescription(purificationOmenLogicActionFace.ActionFace.ActionValue).RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese(), Smart.Format(base.localizationManager.GetLocalizedEffectYouHave(), chantingEffect.GetEffectName()));
		string text = "";
		if (GameScenesUtils.IsBattleScene())
		{
			text = "\n" + Smart.Format(base.localizationManager.GetLocalizedPreviewDescription(), purificationOmenLogicActionFace.ActionFace.BattleAction.GetActionDescription(ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsEffectActiveGetAmount(chantingEffect, activateFeedback: false) * purificationOmenLogicActionFace.ActionFace.ActionValue).UppercaseFirst().RemoveLastIfDotOrComma());
		}
		return Smart.Format(GetOmenRawLocalizedDescription(), arg) + "\n" + base.OmenConvertedDescription() + text;
	}
}
